    {
      "id": "voice_evidence",
      "tier": "important",
      "method": "llm",
      "files": [
        "answer.md"
      ],
      "question": "最终回复是否识别出目标通话为弃接、其加权件数为 6，且因没有 ServiceNow 工单关联而不属于电话 FCR 分母，同时说明规范分类为 MFA？",
      "pass_anchor": "必须同时表达以下真实证据链：目标通话 GCR-20251218-R214 的 disposition 是 abandoned，interaction weight/abandoned weight 均为 6；ServiceNow correlation key 为空或缺失；因此该事件不能成为 Help Desk 创建的合格电话事件，不进入电话 FCR 分母；质检观察到的 Multi-Factor Authentication 变体规范化为 MFA。允许中文或英文、自然语言及合理同义表达。"
    },
    {
      "id": "operation_report",
      "tier": "important",
      "method": "llm",
      "files": [
        "answer.md"
      ],
      "question": "最终回复是否明确报告已对目标复核项执行了什么 QA 操作，并给出后态为 confirmed、分类 MFA、关联仍 missing？",
      "pass_anchor": "回复应明确说明已完成目标质检项的确认/更新操作，并报告后态 qa_status=confirmed、规范服务分类=MFA、关联状态保持 missing；可用中文业务表述，不要求逐字字段名。"
    }
  ],
  "check_code": "import hashlib\nimport json\nimport re\nimport sqlite3\nfrom pathlib import Path\n\n\nREVIEW_ID = \"GQA-202512-0043\"\nROLLUP_ID = \"GCR-20251218-R214\"\nOTHER_REVIEWS_SHA256 = \"56fec0e29b91944d6434311d78d9f6d6ff9a38555503161f349b253fa950d11e\"\nROLLUP_SHA256 = \"b29d4f3692886acbb7d435849302638fd399eb654939b2b2ed8e6bf50ae77969\"\n\n\ndef _connection(ws):\n    db = Path(ws).resolve().parent / \"system\" / \"genesys_cloud\" / \"state.db\"\n    con = sqlite3.connect(f\"file:{db}?mode=ro\", uri=True)\n    con.row_factory = sqlite3.Row\n    return con\n\n\ndef _digest(value):\n    raw = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(\",\", \":\"))\n    return hashlib.sha256(raw.encode(\"utf-8\")).hexdigest()\n\n\ndef check_target_review_state(ws):\n    con = _connection(ws)\n    try:\n        row = con.execute(\"SELECT review_id, call_rollup_id, qa_status, confirmed_service_category, correlation_status FROM call_quality_reviews WHERE review_id = ?\", (REVIEW_ID,)).fetchone()\n    finally:\n        con.close()\n    got = dict(row) if row else None\n    expected = {\"review_id\": REVIEW_ID, \"call_rollup_id\": ROLLUP_ID, \"qa_status\": \"confirmed\", \"confirmed_service_category\": \"MFA\", \"correlation_status\": \"missing\"}\n    ok = got == expected\n    return {\"score\": 1 if ok else 0, \"detail\": f\"got={got}, expected={expected}\"}\n\n\ndef check_audit_note(ws):\n    con = _connection(ws)\n    try:\n        row = con.execute(\"SELECT review_note FROM call_quality_reviews WHERE review_id = ?\", (REVIEW_ID,)).fetchone()\n    finally:\n        con.close()\n    note = (row[\"review_note\"] if row else \"\") or \"\"\n    text = re.sub(r\"[^a-z0-9一-龥]+\", \" \", note.lower())\n    groups = {\n        \"mfa\": (\"mfa\", \"multi factor\", \"multi-factor\", \"多因素\", \"多因子\"),\n        \"abandoned\": (\"abandoned\", \"abandon\", \"disconnected\", \"弃接\", \"放弃\", \"未接通\"),\n        \"missing correlation\": (\"no servicenow\", \"missing servicenow\", \"no ticket\", \"without ticket\", \"no correlation\", \"missing correlation\", \"无工单\", \"没有工单\", \"无关联\", \"缺少关联\"),\n        \"fcr exclusion\": (\"fcr denominator\", \"fcr denominator\", \"not in fcr\", \"excluded from fcr\", \"exclude fcr\", \"hd fcr 60m denominator\", \"不进入 fcr\", \"不纳入 fcr\", \"fcr 分母\", \"fcr分母\")\n    }\n    missing = [name for name, variants in groups.items() if not any(v in text for v in variants)]\n    ok = bool(note.strip()) and not missing\n    return {\"score\": 1 if ok else 0, \"detail\": f\"missing={missing}, note={note!r}\"}\n\n\ndef check_other_reviews_unchanged(ws):\n    con = _connection(ws)\n    try:\n        rows = [dict(r) for r in con.execute(\"SELECT * FROM call_quality_reviews WHERE review_id <> ? ORDER BY review_id\", (REVIEW_ID,)).fetchall()]\n    finally:\n        con.close()\n    digest = _digest(rows)\n    ok = len(rows) == 115 and digest == OTHER_REVIEWS_SHA256\n    return {\"score\": 1 if ok else 0, \"detail\": f\"rows={len(rows)}, sha256={digest}\"}\n\n\ndef check_call_rollup_unchanged(ws):\n    con = _connection(ws)\n    try:\n        row = con.execute(\"SELECT * FROM call_interaction_rollup WHERE call_rollup_id = ?\", (ROLLUP_ID,)).fetchone()\n    finally:\n        con.close()\n    digest = _digest(dict(row)) if row else \"\"\n    ok = digest == ROLLUP_SHA256\n    return {\"score\": 1 if ok else 0, \"detail\": f\"sha256={digest}\"}\n",
  "gold_answer": null,
  "input": "both",
  "act": "mutate_db",
  "output": "none",
  "reward": "rl_grade"
}
